WordCount* top_words_from_file(const char* path, const char* const* ignore_words, size_t ignore_words_length, size_t max_results, size_t* result_length) {
    if (result_length != nullptr) *result_length = 0;
    if (path == nullptr || (ignore_words == nullptr && ignore_words_length != 0)) return nullptr;

    try {
        // Build ignore set
        std::unordered_set<std::string> ignore_set;
        ignore_set.reserve(ignore_words_length);
        for (size_t i = 0; i < ignore_words_length; ++i) {
            if (ignore_words[i] != nullptr) {
                std::string word;
                word.reserve(std::strlen(ignore_words[i]));
                for (char c : ignore_words[i]) {
                    if (is_word_char(c)) {
                        word.push_back(normalize_char(c));
                    }
                }
                if (!word.empty()) {
                    ignore_set.insert(std::move(word));
                }
            }
        }

        // Read file
        std::ifstream file(path, std::ios::binary);
        if (!file) throw std::runtime_error("Could not open input file: " + std::string(path));
        file.seekg(0, std::ios::end);
        std::streamsize size = file.tellg();
        if (size < 0) throw std::runtime_error("Could not determine input file size: " + std::string(path));
        file.seekg(0, std::ios::beg);
        std::string text;
        text.resize(static_cast<std::size_t>(size));
        if (size > 0) {
            file.read(text.data(), size);
            if (!file) throw std::runtime_error("Could not read input file: " + std::string(path));
        }

        // Count frequencies
        std::unordered_map<std::string, std::uint64_t> frequencies;
        std::string current_word;
        current_word.reserve(32);
        for (char c : text) {
            if (is_word_char(c)) {
                current_word.push_back(normalize_char(c));
            } else {
                if (!current_word.empty() && ignore_set.find(current_word) == ignore_set.end()) {
                    frequencies[current_word] += 1;
                }
                current_word.clear();
            }
        }
        if (!current_word.empty() && ignore_set.find(current_word) == ignore_set.end()) {
            frequencies[current_word] += 1;
        }

        size_t result_size = std::min(frequencies.size(), max_results);
        if (result_size == 0) return nullptr;

        WordCount* result = static_cast<WordCount*>(std::calloc(result_size, sizeof(WordCount)));
        if (!result) return nullptr;
        auto cleanup = [result_size](WordCount* values) { free_word_counts(values, result_size); };
        std::unique_ptr<WordCount, decltype(cleanup)> result_guard(result, cleanup);

        for (const auto& [word, count] : frequencies) {
            consider_candidate(result, result_size, word, count);
        }

        if (result_length != nullptr) *result_length = result_size;
        return result_guard.release();
    } catch (...) {
        return nullptr;
    }
}

